:::

```{.r .cell-code}
dat$education <- factor(dat$education, levels = c(
  "Lower Secondary", "O Level", "A Level", "National Certificate", "Diploma",
  "National Diploma", "Higher National Diploma", "Bachelor Degree",
  "Master Degree", "PhD"
))
tinyplot(~ education, data = dat, type = "barplot")
```

